using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEditor;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;
public static class CeilingReplicaProbe{
 public static object Run(string output){
  EditorUtility.audioMasterMute=true;Directory.CreateDirectory(output);var w=UnityEngine.Object.FindAnyObjectByType<WatchDemoController>();var original=w.State.Scare;var c=new ScareSequenceState(HorrorTuning.Current){ReadOnly=true};if(!c.Apply(original.Capture()))throw new Exception("Replica rejected the authoritative scene");var parent=new GameObject("Temporary ceiling replica");var replica=new ScareKit(parent.transform);try{replica.Beat(c.Beat,c.Age);replica.Present(c,Camera.main.transform.position);var host=(ScareKit)typeof(NightmareScene).GetField("kit",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(w.GetComponent<NightmareScene>());var f=typeof(ScareKit).GetField("body",BindingFlags.NonPublic|BindingFlags.Instance);var a=(Transform)f.GetValue(host);var b=(Transform)f.GetValue(replica);float position=Vector3.Distance(a.position,b.position),rotation=Quaternion.Angle(a.rotation,b.rotation);bool ok=position<.001f&&rotation<.1f;File.WriteAllText(output+"/result.json","{\"passed\":"+(ok?"true":"false")+",\"positionDifference\":"+position.ToString("F5",System.Globalization.CultureInfo.InvariantCulture)+",\"rotationDifference\":"+rotation.ToString("F5",System.Globalization.CultureInfo.InvariantCulture)+"}");return new{passed=ok,positionDifference=position,rotationDifference=rotation};}finally{replica.Dispose();UnityEngine.Object.Destroy(parent);}
